function LOG_MAHLER(coeffs):
    roots <- DURAND_KERNER(coeffs)
    s <- 0
    for alpha in roots:
        if |alpha| > 1: s <- s + log(|alpha|)
    return s

function DURAND_KERNER(coeffs):
    d <- degree(coeffs); make monic
    z[i] <- seed^i for i in 0..d-1
    repeat until max step < tol:
        for i in 0..d-1:
            den <- product over j!=i of (z[i]-z[j])
            z[i] <- z[i] - P(z[i]) / den
    return z

