function KOOPMAN_MATRIX(i, k):
    basis <- all (e0,e1,e2,e3) with e0+e1+e2+e3 <= k
    M <- zero matrix of size |basis| x |basis|
    for col, e in enumerate(basis):
        img <- PRECOMPOSE(i, monomial(e))      # substitute X_j -> Lambda_{i,j}
        for monomial b with coeff c in img:
            M[index(b)][col] <- c
    return M

function PRECOMPOSE(i, p):
    forms[j] <- sum_l S_i[j,l] * X_l
    return sum over monomials X^e in p of coeff * product_j forms[j]^e_j

